-- Table: `exam_results` (113 rows)
CREATE TABLE IF NOT EXISTS `exam_results` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` int(10) unsigned NOT NULL,
  `exam_type` varchar(50) NOT NULL,
  `exam_month` varchar(20) DEFAULT NULL,
  `exam_year` varchar(10) DEFAULT NULL,
  `exam_date_value` varchar(7) DEFAULT NULL,
  `roll_no` varchar(50) DEFAULT NULL,
  `grand_total` decimal(10,2) DEFAULT NULL,
  `total_hidden` tinyint(1) NOT NULL DEFAULT 0,
  `result_status` varchar(50) DEFAULT NULL,
  `failed_subjects` text DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_result` (`student_id`,`exam_type`,`exam_month`,`exam_year`,`roll_no`),
  CONSTRAINT `fk_exam_results_students` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



